package br.com.sol7.olimpio.basico.comunicacaomensagem.controller;
import br.com.sol7.olimpio.shared.PagedResponse;
import io.smallrye.mutiny.Uni; import jakarta.inject.Inject; import jakarta.validation.Valid; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.List;
import br.com.sol7.olimpio.basico.comunicacaomensagem.dto.ComunicacaoMensagemRequest;
import br.com.sol7.olimpio.basico.comunicacaomensagem.dto.ComunicacaoMensagemResponse;
import br.com.sol7.olimpio.basico.comunicacaomensagem.service.ComunicacaoMensagemService;
@Path("/api/basico/comunicacao-mensagem") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class ComunicacaoMensagemController { @Inject ComunicacaoMensagemService service; @GET public Uni<List<ComunicacaoMensagemResponse>> list(){return service.list();} @GET @Path("/paged") public Uni<PagedResponse<ComunicacaoMensagemResponse>> paged(@QueryParam("page") Integer page,@QueryParam("size") Integer size){return service.paged(page==null?0:page,size==null?10:size);} @GET @Path("/{id}") public Uni<ComunicacaoMensagemResponse> find(@PathParam("id") Long id){return service.find(id);}@POST public Uni<Response> create(@Valid ComunicacaoMensagemRequest r){return service.create(r).map(item->Response.status(Response.Status.CREATED).entity(item).build());}@PUT @Path("/{id}") public Uni<ComunicacaoMensagemResponse> update(@PathParam("id") Long id,@Valid ComunicacaoMensagemRequest r){return service.update(id,r);}@DELETE @Path("/{id}") public Uni<Void> delete(@PathParam("id") Long id){return service.delete(id);} }